insert into public.missions(slug,title,description,category,skills,interests,goal_categories,recommended_age_min,recommended_age_max,difficulty,estimated_minutes,xp_reward,goal_progress_reward,evidence_types,lesson_title,lesson_content)
select slug,title,description,category,skills,interests,goals,min_age,max_age,difficulty,minutes,xp,progress,evidence,lesson_title,
jsonb_build_object('intro','Antes de começar, entenda o que torna esta missão útil na vida real.','steps',jsonb_build_array('Leia o objetivo e defina seu plano.','Execute com segurança e registre o processo.','Revise o resultado antes de enviar.'),'checklist',jsonb_build_array('Entendi o objetivo','Tenho um plano seguro','Sei qual evidência enviar'),'tip',tip)
from seed
on conflict(slug) do update set title=excluded.title,description=excluded.description,category=excluded.category,skills=excluded.skills,interests=excluded.interests,goal_categories=excluded.goal_categories,recommended_age_min=excluded.recommended_age_min,recommended_age_max=excluded.recommended_age_max,difficulty=excluded.difficulty,estimated_minutes=excluded.estimated_minutes,xp_reward=excluded.xp_reward,goal_progress_reward=excluded.goal_progress_reward,evidence_types=excluded.evidence_types,lesson_title=excluded.lesson_title,lesson_content=excluded.lesson_content,status='ACTIVE',updated_at=now();
